{
  "concepts": [
    {
      "title": "...",
      "angle": "...",
      "hook": "...",
      "script": [{ "t": "0-3s", "visual": "...", "voiceover": "...", "on_screen_text": "..." }],
      "cta": "...",
      "midjourney_prompt": "...",
      "kling_prompt": "...",
      "elevenlabs": { "voice_direction": "...", "voiceover_text": "..." },
